=Você faz a etapa 2 (Proposta) da configuração dos Design Tokens de um projeto do laboratório. Recebe as respostas do questionário, o que o código já calculou, a lista das variáveis lidas do arquivo no Figma (a Semântica com a referência atual nos dois modos e a Base com os valores) e a documentação do laboratório, lida do Figma. Você só propõe: um humano aprova, e depois um agente aplica no Figma.

## Regras
0. A documentação do laboratório (no fim) é a fonte das regras e dos limites. Se algo deste prompt for diferente dela, siga a documentação e escreva em "duvidas" o que diferiu.
1. Proponha só as trocas de referência da Semântica que as respostas pedem. Resposta "padrão" não gera troca.
2. Use só nomes que estão nas listas. Nunca crie token, nunca mude nome, nunca invente valor.
3. Toda referência nova aponta para uma variável da Base da lista, nos dois modos (claro e escuro).
4. As trocas de valor da Base (cores da marca, neutro e famílias de fonte) e os grupos apagados já foram feitos pelo código. Não repita.
5. Travado não muda: as escalas da Base e as paletas de feedback.
6. Limites do Ajustável:
   - em space e radius, um tamanho nunca fica maior que o seguinte (small pode ser igual a medium, nunca maior);
   - border-width de 0,5 a 8 px, e border-width/focus nunca abaixo de 2;
   - altura de linha: 1,3 × o tamanho em display e heading, e 1,5 × em body e label, arredondada para o múltiplo de 4 mais próximo (no empate, para cima). Se mudar um font-size, mude a line-height do mesmo papel e tamanho;
   - text/danger e afins só dentro da própria paleta;
   - accent-n só aponta para brand-n;
   - cantos retos: todo radius, menos radius/full, pode apontar para radius/0;
   - typography/{papel}/font-family aponta só para font-family/primary ou /secondary;
   - deslocamento, desfoque e espalhamento de shadow apontam só para space.
7. Onde cada resposta mexe: 6 (fonte do texto) nos font-weight de body e label, se a fonte não tiver 400 e 500; 7 (peso dos títulos) nos font-weight de typography/display e typography/heading; 8 (densidade) em space; 9 (cantos) em radius; 10 (bordas) em border-width/default e border-width/strong; 11 (tamanho dos títulos de destaque) nos font-size e line-height de typography/display; 12 (página e superfícies) em background/canvas e background/surface; o contraste da cor principal em text/on-action-primary e icon/on-action-primary, usando a pré-checagem.
8. Se uma resposta não couber no limite, não force: escreva em "duvidas".

## Dados
{{ $json.contexto_ia }}

## Documentação do laboratório (lida do Figma)
{{ $('Resumir documentação').first().json.documentacao }}

## Formato
Responda só com JSON válido, sem nenhum texto antes ou depois:
{"trocas":[{"token":"space/medium","claro":"space/12","escuro":"space/12","resposta":"8. Densidade","motivo":"uma frase"}],"duvidas":["pergunta curta"]}

parameters.jsCode:
// Transforma as respostas do questionário no que dá para decidir em código: trocas de valor da Base, grupos a apagar, alertas e uma pré-checagem de contraste.
const t = $('Ler tokens').first().json;
const f = t.respostas;
const campo = rotulo => String(f[rotulo] ?? '').trim();
const padrao = v => !v || /^padr[aã]o$/i.test(v);
const naoUsa = v => /n[aã]o usa/i.test(v);
const hexes = v => (v.match(/#?[0-9a-fA-F]{6}\b/g) || []).map(h => '#' + h.replace('#', '').toUpperCase());
const passos = prefixo => Object.keys(t.base).filter(n => n.startsWith(prefixo + '/'))
  .sort((a, b) => Number(a.split('/')[1].replace('_', '.')) - Number(b.split('/')[1].replace('_', '.')));

const trocasBase = [];   // { token, antes, depois, resposta }
function trocar(token, depois, resposta) {
  const antes = t.base[token].valor;
  if (String(antes).toUpperCase() !== String(depois).toUpperCase()) trocasBase.push({ token, antes, depois, resposta });
}
const apagar = [];       // nomes de variáveis a apagar
const alertas = [];

// Perguntas 2 e 3: cores da marca
const marcas = [['brand-1', campo('Cor principal (brand-1)'), '2. Cor principal'],
  ['brand-2', campo('Cor brand-2'), '3. Cores secundárias'],
  ['brand-3', campo('Cor brand-3'), '3. Cores secundárias'],
  ['brand-4', campo('Cor brand-4'), '3. Cores secundárias']];
const coresInformadas = {};
for (const [paleta, resposta, pergunta] of marcas) {
  const nomes = passos(paleta);
  if (paleta === 'brand-1' && naoUsa(resposta)) { alertas.push('2. Cor principal: brand-1 é obrigatória (seção 03). Informe a cor da marca ou deixe "padrão".'); continue; }
  if (paleta !== 'brand-1' && naoUsa(resposta)) {
    // Seção 06 e seção 10: a paleta brand-n sai junto com background/accent-n/*, text/on-accent-n-strong e icon/on-accent-n-strong
    apagar.push(...nomes);
    apagar.push(...Object.keys(t.semantic.light).filter(n => new RegExp(`(^|/|-)accent-paleta.split('-')[1](/|-|)`).test(n)));
    continue;
  }
  if (padrao(resposta)) continue;
  const lista = hexes(resposta);
  if (lista.length === 0) { alertas.push(`pergunta({paleta}): "${resposta}" não tem código de cor. Use #RRGGBB.`); continue; }
  if (lista.length === 1) {
    coresInformadas[paleta] = lista[0];
    alertas.push(`${pergunta} (paleta):sóumacor({lista[0]}). Gere a escala de 50 a 950 no uicolors.app (seção 05) e cole as ${nomes.length} cores no plugin, ou deixe o agente propor na etapa 2 dele. Nada muda na Base por aqui.`);
    continue;
  }
  if (lista.length !== nomes.length) { alertas.push(`${pergunta} (${paleta}): recebi ${lista.length} cores, mas a Base tem nomes.lengthpassos({nomes[0]} a ${nomes[nomes.length - 1]}).`); continue; }
  nomes.forEach((nome, i) => trocar(nome, lista[i], pergunta));
}

// Pergunta 4: neutro. neutral/0 continua branco e /1000 continua preto (seção 05); os passos do meio vão do mais claro ao mais escuro
const neutro = campo('Neutro');
if (!padrao(neutro)) {
  const lista = hexes(campo('Paleta neutra própria'));
  const nomes = passos('neutral').filter(n => !['neutral/0', 'neutral/1000'].includes(n));
  if (lista.length === nomes.length) {
    const escurece = lista.every((h, i) => i === 0 || lum(h) <= lum(lista[i - 1]));
    if (escurece) nomes.forEach((nome, i) => trocar(nome, lista[i], '4. Neutro'));
    else alertas.push(`4. Neutro: a paleta informada não vai do mais claro ao mais escuro (limite do Ajustável, seção 05). Nada muda na Base.`);
  } else if (/pr[oó]pria/i.test(neutro)) {
    alertas.push(`4. Neutro "paleta própria": preciso de nomes.lengthcores({nomes[0]} a ${nomes[nomes.length - 1]}; neutral/0 e /1000 não mudam). Sem elas, nada muda na Base.`);
  } else {
    alertas.push(`4. Neutro "${neutro}": a paleta ${neutro} sai na etapa 2 do agente, dentro do limite da seção 05 (0 branco, 1000 preto, do claro ao escuro). Nada muda na Base por aqui.`);
  }
}

// Perguntas 5 a 7: fontes e pesos. Seção 05: display e heading usam font-family/primary (peso 700); body usa /secondary (400) e label também (500)
for (const [token, rotulo, pergunta] of [['font-family/primary', 'Fonte dos títulos', '5. Fonte dos títulos'], ['font-family/secondary', 'Fonte do texto', '6. Fonte do texto']]) {
  const v = campo(rotulo);
  if (padrao(v)) continue;
  if (!(token in t.base)) { alertas.push(`${pergunta}: ${token} não está na Base do JSON.`); continue; }
  trocar(token, v, pergunta);
}
const pesosTitulo = (campo('Pesos da fonte dos títulos').match(/\d{3}/g) || []).map(Number);
const pesoPedido = padrao(campo('Peso dos títulos')) ? 700 : Number((campo('Peso dos títulos').match(/\d{3}/) || [0])[0]);
if (!padrao(campo('Fonte dos títulos')) && pesosTitulo.length && !pesosTitulo.includes(pesoPedido)) {
  alertas.push(`7. Peso dos títulos: pesoPedidonãoestáentreospesosinformadosdafonte({pesosTitulo.join(', ')}).`);
}

const pesosTexto = (campo('Pesos da fonte do texto').match(/\d{3}/g) || []).map(Number);
if (!padrao(campo('Fonte do texto')) && pesosTexto.length) {
  const faltam = [400, 500].filter(p => !pesosTexto.includes(p));
  if (faltam.length) alertas.push(`6. Fonte do texto: faltam os pesos ${faltam.join(' e ')} (body usa 400 e label usa 500, no Catálogo – Tipografia). A IA precisa trocar a referência de font-weight desses estilos.`);
}

// Pergunta 13: sem gráficos, o grupo data sai inteiro
const temGrafico = /^s/i.test(campo('O projeto tem gráficos?'));
if (!temGrafico) {
  apagar.push(...Object.keys(t.base).filter(n => /^data-\d/.test(n)));
  apagar.push(...Object.keys(t.semantic.light).filter(n => n.startsWith('data/')));
}

// Pré-checagem de contraste da cor principal (a conferência final é o T-09 do agente)
function lum(hex) {
  const c = [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map(v => (v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)));
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
const contraste = (a, b) => { const [x, y] = [lum(a), lum(b)].sort((m, n) => n - m); return (x + 0.05) / (y + 0.05); };
const refAcao = t.semantic.light['background/action/primary']?.ref;
const novaBase = Object.fromEntries(trocasBase.map(x => [x.token, x.depois]));
const corAcao = coresInformadas['brand-1'] || novaBase[refAcao] || t.base[refAcao]?.valor;
const precheck = [];
if (corAcao) {
  const textoAtual = t.semantic.light['text/on-action-primary']?.ref || '?';
  for (const fundo of ['neutral/0', 'neutral/900']) {
    const cor = t.base[fundo]?.valor;
    if (!cor) continue;
    const r = contraste(corAcao, cor);
    precheck.push(`${fundo} (${cor}) sobre a cor da ação ${corAcao}: ${r.toFixed(2)}:1 ${r >= 4.5 ? 'passa' : 'não passa'} 4,5:1`);
  }
  precheck.push(`Hoje text/on-action-primary aponta para ${textoAtual} no modo claro.`);
}

const apagarUnicos = [...new Set(apagar)];
const respostas = [
  `1. Nome do projeto: ${campo('Nome do projeto')}`,
  `2. Cor principal: ${campo('Cor principal (brand-1)') || 'padrão'}`,
  `3. Secundárias: brand-2 ${campo('Cor brand-2') || 'padrão'}; brand-3 ${campo('Cor brand-3') || 'padrão'}; brand-4 ${campo('Cor brand-4') || 'padrão'}`,
  `4. Neutro: ${neutro || 'padrão'}`,
  `5. Fonte dos títulos: campo('Fontedostítulos')||'padrão'({campo('Pesos da fonte dos títulos') || 'pesos não informados'})`,
  `6. Fonte do texto: campo('Fontedotexto')||'padrão'({campo('Pesos da fonte do texto') || 'pesos não informados'})`,
  `7. Peso dos títulos: ${campo('Peso dos títulos') || 'padrão'}`,
  `8. Densidade: ${campo('Densidade') || 'padrão'}`,
  `9. Cantos: ${campo('Cantos') || 'padrão'}`,
  `10. Bordas: ${campo('Bordas') || 'padrão'}`,
  `11. Tamanho dos títulos de destaque: ${campo('Tamanho dos títulos de destaque') || 'padrão'}`,
  `12. Página e superfícies: ${campo('Página e superfícies') || 'padrão'}`,
  `13. Gráficos: ${temGrafico ? 'sim' : 'não'}`,
].join('\n');

const listaSemantica = Object.keys(t.semantic.light).filter(n => !apagarUnicos.includes(n))
  .map(n => `${n} | claro: ${t.semantic.light[n].ref || t.semantic.light[n].valor} | escuro: ${t.semantic.dark[n]?.ref || t.semantic.dark[n]?.valor}`).join('\n');
const listaBase = Object.keys(t.base).filter(n => !apagarUnicos.includes(n))
  .map(n => `${n} = ${novaBase[n] ?? t.base[n].valor}`).join('\n');

const contexto_ia = [
  'RESPOSTAS DO QUESTIONÁRIO', respostas, '',
  'JÁ CALCULADO EM CÓDIGO (não repita)',
  `Trocas de valor na Base: ${trocasBase.length ? trocasBase.map(x => `${x.token}: ${x.antes} → ${x.depois}`).join('; ') : 'nenhuma'}`,
  `Grupos apagados: ${apagarUnicos.length} variáveis`,
  `Pré-checagem de contraste: ${precheck.join(' · ') || 'sem cor da ação para medir'}`,
  `Alertas: ${alertas.join(' | ') || 'nenhum'}`, '',
  'SEMÂNTICA (nome | referência atual nos dois modos)', listaSemantica, '',
  'BASE (nome = valor, já com as trocas acima)', listaBase,
].join('\n');

return [{ json: {
  projeto: campo('Nome do projeto'),
  respostas, trocasBase, apagar: apagarUnicos, alertas, precheck, temGrafico, contexto_ia,
  contagem: {
    base: [t.contagem.base, t.contagem.base - apagarUnicos.filter(n => n in t.base).length],
    semantic: [t.contagem.semantic, t.contagem.semantic - apagarUnicos.filter(n => n in t.semantic.light).length],
  },
} }];

// Audita em código a proposta da IA: nomes que existem, referências para a Base, Travados e limites do Ajustável.
const t = $('Ler tokens').first().json;
const r = $('Conferir respostas').first().json;
const texto = $('Proposta').first().json.text || '';

let proposta;
try {
  const limpo = texto.replace(/`{3}(json)?/g, '');
  proposta = JSON.parse(limpo.slice(limpo.indexOf('{'), limpo.lastIndexOf('}') + 1));
} catch (e) {
  throw new Error('A IA não devolveu um JSON válido. Rode o nó Proposta de novo. Início da resposta: ' + texto.slice(0, 200));
}
const trocas = Array.isArray(proposta.trocas) ? proposta.trocas : [];
const duvidas = Array.isArray(proposta.duvidas) ? proposta.duvidas : [];

const valorBase = Object.fromEntries(Object.entries(t.base).map(([n, v]) => [n, v.valor]));
for (const x of r.trocasBase) valorBase[x.token] = x.depois;
const num = v => Number(String(v).replace(',', '.'));
const feedback = ['danger', 'warning', 'success', 'information'];
const paletaDe = ref => (ref || '').split('/')[0];

// 1. Cada troca, uma por uma
const resultado = trocas.map(x => {
  const token = String(x.token || '').trim();
  const claro = String(x.claro || '').trim();
  const escuro = String(x.escuro || '').trim();
  const motivos = [];
  const atual = t.semantic.light[token];
  if (!atual) motivos.push('T-01: o token não existe na Semântica');
  if (r.apagar.includes(token)) motivos.push('T-08: o token é de um grupo que vai ser apagado');
  for (const [modo, ref] of [['claro', claro], ['escuro', escuro]]) {
    if (!(ref in t.base)) motivos.push(`T-03: a referência ${modo} "${ref}" não existe na Base`);
    else if (r.apagar.includes(ref)) motivos.push(`T-08: a referência ${modo} "${ref}" vai ser apagada`);
  }
  if (atual) {
    const pAtual = paletaDe(atual.ref);
    if (feedback.includes(pAtual) && (paletaDe(claro) !== pAtual || paletaDe(escuro) !== pAtual)) motivos.push(`T-05: ${token} precisa ficar dentro da paleta ${pAtual}`);
    const acc = token.match(/accent-(\d)/);
    if (acc && (paletaDe(claro) !== `brand-${acc[1]}` || paletaDe(escuro) !== `brand-acc[1]`))motivos.push(`T-05:accent-{acc[1]} só aponta para brand-${acc[1]}`);
  }
  if (token === 'radius/full' && (claro !== 'radius/full' || escuro !== 'radius/full')) motivos.push('T-05: radius/full continua radius/full, mesmo com cantos retos');
  if (/^typography\/[^/]+\/font-family$/.test(token) && ![claro, escuro].every(ref => /^font-family\/(primary|secondary)$/.test(ref))) motivos.push('T-05: a família aponta só para font-family/primary ou /secondary');
  if (/^shadow\/[^/]+\/(offset-x|offset-y|blur|spread)$/.test(token) && ![claro, escuro].every(ref => ref.startsWith('space/'))) motivos.push('T-05: deslocamento, desfoque e espalhamento da sombra apontam só para space');
  if (token.startsWith('border-width/')) {
    for (const ref of [claro, escuro]) {
      const v = num(valorBase[ref]);
      if (!(v >= 0.5 && v <= 8)) motivos.push(`T-05: border-width fora de 0,5 a 8 px (${ref} = ${valorBase[ref]})`);
      if (token === 'border-width/focus' && v < 2) motivos.push('T-05: o foco nunca fica abaixo de 2 px');
    }
  }
  return {
    token, claro, escuro,
    antes: atual ? `${atual.ref || atual.valor} | ${t.semantic.dark[token]?.ref || t.semantic.dark[token]?.valor}` : '—',
    resposta: x.resposta || '', motivo: x.motivo || '',
    ok: motivos.length === 0, problemas: [...new Set(motivos)],
  };
});

// 2. Conjunto depois das trocas aprovadas: um tamanho nunca maior que o seguinte em space e radius
const depois = {};
for (const modo of ['light', 'dark']) {
  depois[modo] = Object.fromEntries(Object.entries(t.semantic[modo]).map(([n, v]) => [n, v.ref]));
  for (const x of resultado.filter(y => y.ok)) depois[modo][x.token] = modo === 'light' ? x.claro : x.escuro;
}
const ordem = ['none', 'xx-small', 'x-small', 'small', 'medium', 'large', 'x-large', 'xx-large'];
const conjunto = [];
for (const grupo of ['space', 'radius']) {
  let anterior = null;
  for (const tamanho of ordem) {
    const nome = `${grupo}/${tamanho}`;
    if (!(nome in depois.light)) continue;
    const v = num(valorBase[depois.light[nome]]);
    if (anterior && v < anterior.v) conjunto.push(`T-05: anterior.nome({anterior.v}) ficou maior que nome({v})`);
    anterior = { nome, v };
  }
}

// 3. Altura de linha (seção 05): 1,3 × em display e heading, 1,5 × em body e label, arredondada para o múltiplo de 4 mais próximo; no empate, para cima
const alturas = Object.keys(valorBase).filter(n => n.startsWith('line-height/')).map(n => num(valorBase[n]));
for (const nome of Object.keys(depois.light).filter(n => /^typography\/[^/]+\/[^/]+\/font-size$/.test(n))) {
  const papel = nome.split('/')[1];
  const fator = ['display', 'heading'].includes(papel) ? 1.3 : 1.5;
  const tamanho = num(valorBase[depois.light[nome]]);
  const linha = nome.replace('font-size', 'line-height');
  if (!(linha in depois.light) || !alturas.length || !tamanho) continue;
  const esperado = Math.round((tamanho * fator) / 4) * 4;
  const atual = num(valorBase[depois.light[linha]]);
  if (!alturas.includes(esperado)) conjunto.push(`Alerta T-05: ${linha} deveria ser esperado({fator} × tamanho),masline-height/{esperado} não está na Base`);
  else if (atual !== esperado) conjunto.push(`T-05: ${linha} = ${atual}, mas ${fator} × ${tamanho} = ${(tamanho * fator).toFixed(1)}, que arredonda para ${esperado}`);
}

const aprovadas = resultado.filter(x => x.ok);
const reprovadas = resultado.filter(x => !x.ok);
const linhaTroca = x => `${x.token}: ${x.antes} → ${x.claro} | x.escuro({x.resposta}${x.motivo ? '; ' + x.motivo : ''})`;
const resumo = [
  `Projeto: ${r.projeto}`,
  `Trocas na Base (do questionário, em código): ${r.trocasBase.length}`,
  `Trocas na Semântica propostas pela IA: ${trocas.length} · passaram na auditoria: ${aprovadas.length} · reprovadas: ${reprovadas.length}`,
  `Variáveis a apagar (grupos opcionais): ${r.apagar.length}`,
  '',
  'TROCAS QUE PASSARAM', aprovadas.map(linhaTroca).join('\n') || 'nenhuma', '',
  'TROCAS REPROVADAS PELA AUDITORIA', reprovadas.map(x => `${linhaTroca(x)} → ${x.problemas.join('; ')}`).join('\n') || 'nenhuma', '',
  'CONJUNTO DEPOIS DAS TROCAS', conjunto.join('\n') || 'sem problemas em space, radius e altura de linha', '',
  'ALERTAS DO QUESTIONÁRIO', r.alertas.join('\n') || 'nenhum', '',
  'PRÉ-CHECAGEM DE CONTRASTE DA COR PRINCIPAL', r.precheck.join('\n') || '—', '',
  'DÚVIDAS DA IA', duvidas.join('\n') || 'nenhuma',
].join('\n');

return [{ json: { aprovadas, reprovadas, conjunto, duvidas, resumo } }];
